cssCode:
.laser-card {
  position: relative; width: 220px; height: 320px;
  background: #050505; border-radius: 15px;
  display: flex; align-items: center; justify-content: center;
  overflow: hidden;
}
.laser-card::before {
  content: ''; position: absolute;
  width: 150%; height: 150%;
  background: conic-gradient(transparent, transparent, transparent, #00ffcc, #ff007f);
  animation: spinLaser 3s linear infinite;
}
.laser-card::after {
  content: 'LASER FOCUS'; position: absolute;
  inset: 3px; background: #111; border-radius: 12px;
  display: flex; align-items: center; justify-content: center;
  color: #fff; font-family: sans-serif; font-weight: bold; font-size: 20px;
  letter-spacing: 2px;
}
@keyframes spinLaser { 100% { transform: rotate(360deg); } }

